create table if not exists public.nail_2nya_customer_push_subscriptions (id uuid primary key default gen_random_uuid(),appointment_id uuid not null references public.nail_2nya_appointments(id) on delete cascade,endpoint text not null unique,p256dh text not null,auth text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists nail_2nya_customer_push_appointment_idx on public.nail_2nya_customer_push_subscriptions(appointment_id) where active=true; create table if not exists public.nail_2nya_notification_deliveries (id uuid primary key default gen_random_uuid(),appointment_id uuid not null references public.nail_2nya_appointments(id) on delete cascade,event_type text not null,target text not null check (target in ('admin','customer')),created_at timestamptz not null default now(),unique(appointment_id,event_type,target));